def transform(grid):
    n = len(grid[0])
    c = grid[0].index(2)
    out = [[0] * n for _ in range(n)]
    reach = min(c, n - 1 - c)
    for r in range(n):
        for col in range(n):
            if abs(col - c) == r and r <= reach:
                out[r][col] = 2
    for r in range(3, n):
        for col in range(n):
            inside_wedge = r <= reach and abs(col - c) < r
            below_wedge = r > reach
            # The diagonal lattice is phase-aligned to the apex, with an offset visible in the demo.
            if (inside_wedge or below_wedge) and (col - r - c) % 4 == 0 and out[r][col] == 0:
                out[r][col] = 1
    return out
